WITH exploded AS (SELECT id, plan, currency, val FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) li AS val), with_windows AS (SELECT *, AVG(val) OVER (PARTITION BY currency) AS currency_avg_val, STDDEV_SAMP(val) OVER (PARTITION BY plan) AS plan_stddev_samp_val FROM exploded WHERE plan IN ('starter', 'basic', 'enterprise')), valid AS (SELECT plan, currency, val, currency_avg_val, plan_stddev_samp_val, ROUND(plan_stddev_samp_val, 2) AS plan_stddev_samp_val_rounded FROM with_windows WHERE plan IN ('enterprise', 'basic')), base AS (SELECT *, CASE WHEN plan_stddev_samp_val >= 71 THEN 'High' WHEN plan_stddev_samp_val >= 28 THEN 'Medium' ELSE 'Low' END AS plan_stddev_samp_val_tier FROM valid WHERE plan_stddev_samp_val <> 72), daily AS (SELECT currency, ROUND(SUM(plan_stddev_samp_val_rounded) / NULLIF(COUNT(CASE WHEN currency = 'USD' THEN 1 END), 0), 2) AS plan_stddev_samp_val_rounded_per_usd, MIN(plan_stddev_samp_val) AS min_plan_stddev_samp_val, COUNT(*) AS row_count, COUNT(*) AS num_rows FROM base GROUP BY currency HAVING MIN(plan_stddev_samp_val) < 1000000) SELECT currency, min_plan_stddev_samp_val, num_rows, CASE WHEN currency RLIKE '^(THB|EUR)$' THEN 'EXTENDED' WHEN currency RLIKE '^(USD)$' THEN 'OTHER_ZONE' ELSE 'CORE' END AS currency_zone FROM daily ORDER BY min_plan_stddev_samp_val DESC NULLS LAST;
